pub enum SimError {
    Halted,
    UndefinedTransition,
    Overflow
}
impl fmt::Display for SimError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Halted => write!(f, "Halted"),
            Self::UndefinedTransition => write!(f, "Undefined transition"),
            Self::Overflow => write!(f, "Overflow"),
        }
    }
}

